import React, { useState, useEffect, useCallback } from "react";
import { Search, X, Trello, Clock, Hash } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useWorkspace } from "../context/WorkspaceContext";
import api from "../utils/api";

const GRADIENTS = [
  "linear-gradient(135deg,#667eea,#764ba2)",
  "linear-gradient(135deg,#f093fb,#f5576c)",
  "linear-gradient(135deg,#4facfe,#00f2fe)",
  "linear-gradient(135deg,#43e97b,#38f9d7)",
  "linear-gradient(135deg,#fa709a,#fee140)",
  "linear-gradient(135deg,#a18cd1,#fbc2eb)",
];

const BoardResult = ({ board, onClick }) => (
  <button
    onClick={onClick}
    style={{
      display: "flex", alignItems: "center", gap: 12,
      padding: "10px 14px", borderRadius: "var(--radius-md)",
      background: "var(--bg-card)", border: "1px solid var(--border-subtle)",
      cursor: "pointer", width: "100%", textAlign: "left",
      transition: "all var(--duration-fast)",
    }}
    onMouseEnter={e => e.currentTarget.style.background = "var(--bg-hover)"}
    onMouseLeave={e => e.currentTarget.style.background = "var(--bg-card)"}
  >
    <div style={{
      width: 36, height: 36, borderRadius: "var(--radius-sm)", flexShrink: 0,
      background: board.background?.value || GRADIENTS[0],
    }} />
    <div style={{ flex: 1, minWidth: 0 }}>
      <p style={{ fontSize: 14, fontWeight: 600, color: "var(--text-primary)", margin: 0 }}>
        {board.title}
      </p>
      <p style={{ fontSize: 12, color: "var(--text-secondary)", margin: 0 }}>
        <Clock size={10} style={{ display: "inline", marginRight: 4 }} />
        {new Date(board.lastActivity || board.updatedAt).toLocaleDateString("en-US", {
          month: "short", day: "numeric", year: "numeric"
        })}
      </p>
    </div>
    <Trello size={14} style={{ color: "var(--text-tertiary)", flexShrink: 0 }} />
  </button>
);

const SearchPage = () => {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searched, setSearched] = useState(false);
  const { activeWorkspace } = useWorkspace();
  const navigate = useNavigate();

  const doSearch = useCallback(async (q) => {
    if (!q.trim() || !activeWorkspace) return;
    setLoading(true);
    setSearched(true);
    try {
      const { data } = await api.get(`/workspaces/${activeWorkspace._id}/boards`);
      const boards = (data.boards || []).filter(b =>
        b.title.toLowerCase().includes(q.toLowerCase()) ||
        b.description?.toLowerCase().includes(q.toLowerCase())
      );
      setResults(boards);
    } catch {
      setResults([]);
    } finally {
      setLoading(false);
    }
  }, [activeWorkspace]);

  useEffect(() => {
    const t = setTimeout(() => { if (query.trim()) doSearch(query); }, 350);
    return () => clearTimeout(t);
  }, [query, doSearch]);

  return (
    <div style={{ maxWidth: 680, margin: "0 auto", padding: "36px 24px" }}>
      {/* Header */}
      <div style={{ marginBottom: 28 }}>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: "var(--text-primary)", marginBottom: 4 }}>
          Search
        </h1>
        <p style={{ fontSize: 14, color: "var(--text-secondary)" }}>
          Find boards across your workspace
        </p>
      </div>

      {/* Search bar */}
      <div style={{ position: "relative", marginBottom: 24 }}>
        <Search
          size={18}
          style={{
            position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)",
            color: "var(--text-tertiary)", pointerEvents: "none",
          }}
        />
        <input
          autoFocus
          value={query}
          onChange={e => setQuery(e.target.value)}
          placeholder="Search boards, cards, members…"
          style={{
            width: "100%", padding: "13px 44px",
            borderRadius: "var(--radius-lg)",
            background: "var(--bg-card)", border: "1.5px solid var(--border-default)",
            color: "var(--text-primary)", fontSize: 15, fontFamily: "inherit",
            outline: "none",
            boxShadow: "var(--shadow-sm)",
            transition: "border-color var(--duration-fast), box-shadow var(--duration-fast)",
          }}
          onFocus={e => {
            e.target.style.borderColor = "var(--border-focus)";
            e.target.style.boxShadow = "0 0 0 3px rgba(139,92,246,.15)";
          }}
          onBlur={e => {
            e.target.style.borderColor = "var(--border-default)";
            e.target.style.boxShadow = "var(--shadow-sm)";
          }}
        />
        {query && (
          <button
            onClick={() => { setQuery(""); setResults([]); setSearched(false); }}
            style={{
              position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)",
              background: "transparent", border: "none", cursor: "pointer",
              color: "var(--text-tertiary)", display: "flex",
            }}
          >
            <X size={16} />
          </button>
        )}
      </div>

      {/* Results */}
      {loading && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {[1, 2, 3].map(i => (
            <div key={i} className="skeleton" style={{ height: 60, borderRadius: "var(--radius-md)" }} />
          ))}
        </div>
      )}

      {!loading && searched && results.length === 0 && (
        <div style={{ textAlign: "center", padding: "48px 0" }}>
          <div style={{ fontSize: 40, marginBottom: 12 }}>🔍</div>
          <p style={{ fontSize: 15, color: "var(--text-secondary)", fontWeight: 500 }}>
            No results for "{query}"
          </p>
          <p style={{ fontSize: 13, color: "var(--text-tertiary)" }}>
            Try a different search term
          </p>
        </div>
      )}

      {!loading && results.length > 0 && (
        <div>
          <p style={{ fontSize: 12, fontWeight: 700, color: "var(--text-tertiary)", textTransform: "uppercase", letterSpacing: ".06em", marginBottom: 10 }}>
            Boards · {results.length} result{results.length !== 1 ? "s" : ""}
          </p>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {results.map(b => (
              <BoardResult key={b._id} board={b} onClick={() => navigate(`/boards/${b._id}`)} />
            ))}
          </div>
        </div>
      )}

      {!searched && (
        <div style={{ textAlign: "center", padding: "60px 0" }}>
          <div style={{
            width: 64, height: 64, borderRadius: "var(--radius-xl)",
            background: "var(--bg-card)", border: "1px solid var(--border-subtle)",
            display: "flex", alignItems: "center", justifyContent: "center",
            margin: "0 auto 16px", fontSize: 28,
          }}>
            🔍
          </div>
          <p style={{ fontSize: 15, color: "var(--text-secondary)", fontWeight: 500 }}>
            Start typing to search
          </p>
          <p style={{ fontSize: 13, color: "var(--text-tertiary)", marginTop: 4 }}>
            Search across boards in {activeWorkspace?.name || "your workspace"}
          </p>
        </div>
      )}
    </div>
  );
};

export default SearchPage;
